mapper.select:
select t.task_id, t.user_id, t.subject_id, t.tag_id, t.task_name, t.description, t.deadline, t.priority, t.status, t.remind_time, t.create_time, t.finish_time, /* 计算子任务完成百分比：若无子任务返回0 */ (SELECT CASE WHEN COUNT(ts.subtask_id)=0 THEN 0 ELSE FLOOR(SUM(CASE WHEN s.status = '已完成' THEN 1 ELSE 0 END)*100/COUNT(ts.subtask_id)) END FROM task_sub ts LEFT JOIN subtask s ON ts.subtask_id = s.subtask_id WHERE ts.task_id = t.task_id ) AS subtask_percent, s.subject_name, (SELECT GROUP_CONCAT(tg.tag_name) FROM tag tg WHERE FIND_IN_SET(CAST(tg.tag_id AS CHAR), t.tag_id) > 0 ) AS tag_names from task t left join subject s on t.subject_id = s.subject_id
AND user_id = #{query.userId}
AND subject_id = #{query.subjectId}
AND task_name like concat('%',#{query.taskName},'%')
AND priority = #{query.priority}
AND status = #{query.status}
